"""Generated by genrec-mcp for one Stage3 run.

The Stage2 SID path and the variant name below are the values passed to the
stage3_start tool call; nothing here is hardcoded in the repository, and the
trainer itself still receives no command-line arguments.

The file has two roles. The parent process is deliberately lightweight: it only
stages the pure-Python Hugging Face packages to a node-local cache and starts
torchrun/one child. The heavy trainer import happens exactly once per training
rank, never in the parent before the spawn.
"""
import os
import subprocess
import sys
import sysconfig
import time
from pathlib import Path

SID = '/fs04/ar57/wenyu/GeneRec/results/stage2_RQ-VAE/_runs/stage2_ae668bc04dc44d52a8bed5f9408e8e74/TIGER_frozen_topology_gnn_rq/result/item_sids.json'
VARIANT = 'issue264_diag'
STAGE3_DIR = '/fs04/ar57/wenyu/GeneRec/stage3_T5Train'
RESULT_ROOT = '/fs04/ar57/wenyu/GeneRec/results/stage3_T5Train'
PER_USER_DUMP = False
REPO = '/fs04/ar57/wenyu/GeneRec'
LAUNCHED_ENV = "GENREC_STAGE3_LAUNCHED"


def _stage3_worker():
    import importlib.util
    if STAGE3_DIR not in sys.path:
        sys.path.insert(0, STAGE3_DIR)
    spec = importlib.util.spec_from_file_location(
        "genrec_stage3_param", os.path.join(STAGE3_DIR, "train_HG-Rec.py"))
    if spec is None or spec.loader is None:
        raise RuntimeError("could not load the Stage3 trainer")
    trainer = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(trainer)
    trainer.CODE_PATH = SID
    trainer.RQVAE_VARIANT = VARIANT
    trainer.LOG_PATH = os.path.join(RESULT_ROOT, VARIANT, "logs") + os.sep
    trainer.SAVE_PATH = os.path.join(RESULT_ROOT, VARIANT, "ckpt") + os.sep
    trainer.PER_USER_DUMP = PER_USER_DUMP
    trainer.main()


def _stage3_parent():
    # This branch must stay stdlib-only. It is the measured cold-start path;
    # importing torch/transformers here would make every launch pay that cost
    # once before torchrun even exists.
    log = os.path.join(RESULT_ROOT, VARIANT, "logs", "_stage3_launcher.log")
    os.makedirs(os.path.dirname(log), exist_ok=True)
    def phase(message):
        with open(log, "ab") as handle:
            handle.write(("[" + time.strftime("%Y-%m-%dT%H:%M:%S") + "] " + message + "\n").encode("utf-8"))
    phase("parent start; staging retained dependencies")
    if REPO not in sys.path:
        sys.path.insert(0, REPO)
    from tools.stage3.startup_cache import prepare
    cache = prepare(sysconfig.get_paths()["purelib"])
    phase("dependency staging ready: " + (str(cache) if cache else "source fallback"))
    env = os.environ.copy()
    if cache is not None:
        env["PYTHONPATH"] = str(cache) + os.pathsep + env.get("PYTHONPATH", "")
    env.update({
        "NCCL_IB_DISABLE": "1",
        "NCCL_P2P_DISABLE": "1",
        "NCCL_SHM_DISABLE": "1",
        "NCCL_TIMEOUT": "3600",
        "TORCH_NCCL_BLOCKING_WAIT": "1",
    })
    if os.environ.get("GENREC_STAGE3_PREWARM", "1") != "0":
        phase("prewarming torch/transformers in a separate process")
        prewarm = subprocess.run(
            [sys.executable, "-c", "import torch, transformers"],
            env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        phase("prewarm exit=" + str(prewarm.returncode))
    script = os.path.abspath(__file__)
    mode = os.environ.get("GENREC_STAGE3_MODE", "ddp")
    if mode == "single-gpu":
        env["GENREC_SINGLE_GPU"] = "1"
        env[LAUNCHED_ENV] = "1"
        cmd = [sys.executable, script]
        banner = "[RecBole HG-Rec] launching single-GPU run (lightweight parent)"
        phase("spawning single-GPU child")
    else:
        torchrun = os.path.join(os.path.dirname(sys.executable), "torchrun")
        cmd = [torchrun, "--standalone", "--nproc_per_node=4",
               "--master_port=50201", script]
        banner = "[RecBole HG-Rec] launching 4-GPU DDP run (lightweight parent)"
        phase("spawning 4-rank torchrun")
    with open(log, "ab") as fout:
        fout.write((banner + "\n").encode("utf-8"))
        fout.flush()
        rc = subprocess.call(cmd, stdout=fout, stderr=subprocess.STDOUT, env=env)
    raise SystemExit(rc)


if __name__ == "__main__":
    if "RANK" in os.environ or os.environ.get(LAUNCHED_ENV):
        _stage3_worker()
    else:
        _stage3_parent()
